import {createLocalManagementUI} from './local-management-ui.js?v=20261022-gestao';
import {mountEvents,readEvents,refreshEventPhotos} from '../local/event-editor.js';
import {mountBusinessLogo} from '../local/business-logo.js?v=20260926-logo';
import {sectors,itemExtras,readItemExtras,refreshItemPhotos} from '../local/sector-config.js';
export function createLocalAdminUI({api,esc,openDialog,closeDialog,toast,uploadFile,getState}){
 let active=false,rows=[],seq=0,editingPhotos=[],inviteDraft=null,editingSector='Outro',editingLogo='';
 const management=createLocalManagementUI({api,esc,openDialog,closeDialog,toast,getState,refresh:()=>load()});
 const states=['Rascunho','Em análise','Publicado','Pausado','Rejeitado','Inativo'];
 document.addEventListener('click',e=>{const button=e.target.closest('[data-local-review]');if(!active||!button)return;const r=rows.find(b=>b.id===button.dataset.localReview);if(!r)return;openDialog('Revisar página · '+r.name,`<form id="local-review" data-id="${esc(r.id)}" data-version="${r.version}"><p>Confira o conteúdo em Conferir página antes de aprovar. A decisão vale para esta versão da página.</p><label>Decisão<select name="state">${r.state==='Publicado'?'<option value="Pausado">Retirar da vitrine</option>':'<option value="Publicado">Aprovar e publicar</option><option value="Rejeitado">Recusar</option>'}</select></label><label>Orientação para o responsável<textarea name="reason" maxlength="1000"></textarea></label><p>Ao recusar, explique o que precisa ser corrigido. O responsável poderá editar e reenviar pelo portal.</p><p role="alert"></p><button class="p-button primary">Confirmar decisão</button></form>`);});
 document.addEventListener('submit',async e=>{if(!active||e.target.id!=='local-review')return;e.preventDefault();const f=e.target,b=f.querySelector('button');b.disabled=true;try{await api('/api/portal/local-admin','POST',{...Object.fromEntries(new FormData(f)),action:'moderate',id:f.dataset.id,version:Number(f.dataset.version)});closeDialog();toast('Revisão salva.');await load();}catch(err){f.querySelector('[role=alert]').textContent=err.message;}finally{b.disabled=false;}});
 const options=(list,v)=>list.map(x=>`<option ${x===v?'selected':''}>${esc(x)}</option>`).join('');
 function page(){return '<section class="page-heading"><div><p class="overline">HELPU LOCAL · ADMINISTRAÇÃO</p><h1>Contas, empresas e produtos.</h1><p>Acompanhe os anunciantes, revise publicações e cuide do catálogo em um só lugar.</p></div></section>'+management.page()+'<section id="local-business-panel" hidden><div class="lm-toolbar"><a class="p-button secondary" href="/local/cadastro.html?tipo=empresa" target="_blank" rel="noopener">Abrir cadastro de empresa ↗</a><a class="p-button secondary" href="/local" target="_blank" rel="noopener">Ver catálogo público ↗</a><button class="p-button secondary" data-local-launch>Plano da Helpu Local</button></div><div class="admin-box local-admin"><label>Buscar empresa<input id="local-search" type="search" placeholder="Negócio, responsável ou telefone"></label><label>Situação da página<select id="local-filter"><option value="">Todas</option>'+options([...states,'Excluídas'],'')+'</select></label><p id="local-count" role="status"></p><div id="local-list">Carregando…</div></div></section>';}
 document.addEventListener('click',e=>{if(!active||!e.target.closest('[data-local-launch]'))return;openDialog('Plano da Helpu Local','<p>O catálogo está aberto ao público. Empresas e produtos aparecem após aprovação da equipe.</p><p>Plano: <strong>R$ 89,90/mês</strong>. A cobrança via Stripe ainda não está ativa. A abertura do catálogo não contrata uma assinatura nem inicia cobranças.</p>');});
 function draw(){if(!active)return;const q=(document.querySelector('#local-search')?.value||'').toLowerCase(),state=document.querySelector('#local-filter')?.value;const selected=rows.filter(r=>(state==='Excluídas'?!!r.deletedAt:!r.deletedAt&&(!state||r.state===state))&&(r.name+' '+r.owner+' '+r.phone).toLowerCase().includes(q));document.querySelector('#local-count').textContent=selected.length+' cadastro(s)';document.querySelector('#local-list').innerHTML=selected.length?selected.map(r=>r.deletedAt?`<article class="admin-box"><p class="overline">Excluída do catálogo</p><h2>${esc(r.name)}</h2><p>A empresa e seus anúncios estão fora do público.</p><button class="p-button secondary" data-local-restore="${esc(r.id)}">Restaurar cadastro</button></article>`:`<article class="admin-box"><p class="overline">${esc(r.sector)} · ${esc(r.state)}</p><h2>${esc(r.name)}</h2><p>${esc(r.owner)} · +${esc(r.phone)}</p><p>Recebido em ${new Date(r.createdAt).toLocaleDateString('pt-BR')}</p><button class="p-button primary" data-local-edit="${esc(r.id)}">Conferir página</button>${['Em análise','Publicado'].includes(r.state)?` <button class="p-button primary" data-local-review="${esc(r.id)}">${r.state==='Publicado'?'Retirar página':'Aprovar ou recusar'}</button>`:''} ${management.notifyButton(r.id)} <button class="p-button secondary" data-local-requests="${esc(r.id)}">Solicitações recebidas</button> <button class="p-button secondary" data-local-invite="${esc(r.id)}">Acesso de cadastro existente</button> <button class="p-button secondary" data-local-delete="${esc(r.id)}">Excluir do catálogo</button> <a class="p-button secondary" href="https://wa.me/${esc(r.phone)}" target="_blank" rel="noopener">Conversar no WhatsApp ↗</a>${r.state==='Publicado'?` <a href="/local/preview.html#/negocio?id=${encodeURIComponent(r.id)}" target="_blank" rel="noopener">Ver página pública ↗</a>`:''}</article>`).join(''):'<p>Nenhum cadastro encontrado. Compartilhe /local/cadastro.html?tipo=empresa para as empresas criarem suas contas.</p>';}
 async function load(){const ticket=++seq;try{const d=await api('/api/portal/local-admin');if(active&&ticket===seq){rows=d.businesses.filter(b=>!b.productsOnly);draw();await management.load(d.businesses);}}catch(e){if(active&&ticket===seq){document.querySelector('#local-list').textContent=e.message;management.error(e.message);}}}
 function edit(r){editingLogo=r.logoId||'';editingSector=r.sector;editingPhotos=[...(r.photos||[])];const field=(name,label,max=300)=>`<label>${label}<input name="${name}" maxlength="${max}" value="${esc(r[name]||'')}" ${['name','owner','phone'].includes(name)?'required':''}></label>`;const area=(name,label,max)=>`<label>${label}<textarea name="${name}" rows="3" maxlength="${max}">${esc(r[name]||'')}</textarea></label>`;openDialog('Preparar · '+r.name,`<form id="local-editor" data-id="${esc(r.id)}" data-version="${r.version}"><div class="business-logo-editor" id="admin-business-logo"></div><h3>Contato privado</h3>${field('name','Nome do negócio',150)}${field('owner','Responsável',100)}${field('phone','WhatsApp do responsável',30)}<label>Segmento<select name="sector">${options(sectors,r.sector)}</select></label><p>Andamento: <strong>${esc(r.state)}</strong>. A revisão é feita em Aprovar ou recusar.</p><input type="hidden" name="state" value="Rascunho">${area('notes','Observações internas · não aparecem no site',5000)}<h3>Página pública</h3><p>Confira as informações enviadas pelo responsável. Ao editar, a página volta a rascunho e precisa ser reenviada pelo portal.</p>${area('description','Descrição do negócio',3000)}${area('offer','Produtos, serviços ou programação · um por linha',3000)}${field('address','Endereço ou região atendida')}${field('hours','Horários',500)}${field('publicPhone','WhatsApp público de atendimento',30)}<h3>Fotos da página</h3><p>A primeira foto será a capa. Sugestão: 1600 × 1000 pixels. Outros tamanhos são aceitos e se adaptam ao espaço sem distorção. Selecione fotos autorizadas pela empresa.</p><div id="local-photos"></div><label>Adicionar fotos · JPG, PNG ou WebP, até 25 MB cada<input id="local-photo-input" type="file" accept="image/jpeg,image/png,image/webp" multiple></label><p id="local-upload-status" role="status"></p><h3>Produtos e serviços</h3><p>Cadastre nome, descrição e preço. Sem preço, o item aparece como “Sob consulta”.</p><div id="local-catalog">${(r.catalog||[]).map(itemRow).join('')}</div><button class="p-button secondary" type="button" data-add-item>Adicionar item</button><h3>Eventos do negócio</h3><div id="admin-events"></div><p>Salvar alterações retira a página do ar até uma nova aprovação. A publicação abre contato pelo WhatsApp; não ativa pagamentos ou reservas automáticas.</p><p id="local-edit-error" role="alert"></p><button type="submit" class="p-button primary">Salvar cadastro</button></form>`,true);drawPhotos();mountEvents(document.querySelector('#admin-events'),r.events||[],()=>editingPhotos);mountBusinessLogo(document.querySelector('#admin-business-logo'),{id:editingLogo,url:editingLogo?'/api/portal/local-admin-photo?business='+encodeURIComponent(r.id)+'&id='+encodeURIComponent(editingLogo):'',upload:async file=>{const a=await uploadFile('/api/portal/'+encodeURIComponent(getState().company.id)+'/files',file);return {...a,url:'/api/portal/local-admin-photo?business='+encodeURIComponent(r.id)+'&id='+encodeURIComponent(a.id)};},onChange:id=>editingLogo=id});}

 function itemRow(x={}){return `<fieldset class="local-item" data-item-id="${esc(x.id||crypto.randomUUID())}"><label>Nome<input data-item-name required maxlength="120" value="${esc(x.name||'')}"></label><label>Descrição<textarea data-item-description maxlength="1000">${esc(x.description||'')}</textarea></label><label>Preço em R$ · deixe vazio para consulta<input data-item-price type="number" min="0" max="1000000" step="0.01" value="${x.priceCents==null?'':x.priceCents/100}"></label>${itemExtras(x,editingSector,esc,editingPhotos)}<label><input data-item-available type="checkbox" ${x.available!==false?'checked':''}> Disponível</label><button type="button" class="p-button secondary" data-remove-item>Remover item</button></fieldset>`;}
 document.addEventListener('change',e=>{if(!active||!e.target.matches('#local-editor [name=sector]'))return;editingSector=e.target.value;for(const el of document.querySelectorAll('#local-catalog .local-item')){const values=readItemExtras(el);el.querySelector('.fields').outerHTML=itemExtras(values,editingSector,esc,editingPhotos);}});
 function drawPhotos(){const form=document.querySelector('#local-editor');if(form){refreshItemPhotos(form,editingPhotos,esc);refreshEventPhotos(form,editingPhotos);}const el=document.querySelector('#local-photos');if(el)el.innerHTML=editingPhotos.map((id,i)=>`<div class="local-photo"><img src="/api/portal/local-admin-photo?business=${encodeURIComponent(document.querySelector('#local-editor').dataset.id)}&amp;id=${encodeURIComponent(id)}" alt="Foto ${i+1}"><span>${i===0?'Capa':'Foto '+(i+1)}</span><button type="button" data-remove-photo="${esc(id)}">Remover</button>${i?`<button type="button" data-cover-photo="${esc(id)}">Usar como capa</button>`:''}</div>`).join('');}
 document.addEventListener('click',async e=>{const button=e.target.closest('[data-local-requests]');if(!active||!button)return;const r=rows.find(x=>x.id===button.dataset.localRequests);if(!r)return;button.disabled=true;try{const d=await api('/api/portal/local-admin','POST',{action:'requests',id:r.id});openDialog('Solicitações · '+r.name,`<p>Reservas e pedidos aguardam confirmação de disponibilidade pela empresa.</p>${d.leads.length?d.leads.map(l=>`<article class="admin-box"><h3>${esc(l.name)}</h3><p>${new Date(l.createdAt).toLocaleString('pt-BR')}</p><p class="local-request-summary">${esc(l.message)}</p><a href="https://wa.me/${encodeURIComponent(l.phone)}" target="_blank" rel="noopener">Responder pelo WhatsApp ↗</a><label>Andamento<select data-local-request="${esc(l.id)}" data-business="${esc(r.id)}" data-version="${l.version}">${options(['Novo','Em atendimento','Confirmado','Concluído','Cancelado'],l.state)}</select></label><p role="status"></p></article>`).join(''):'<p>Nenhuma solicitação recebida ainda.</p>'}`,true);}catch(err){toast(err.message,true);}finally{button.disabled=false;}});
 document.addEventListener('change',async e=>{const el=e.target;if(!active||!el.matches('[data-local-request]'))return;el.disabled=true;try{const d=await api('/api/portal/local-admin','POST',{action:'request-state',id:el.dataset.business,leadId:el.dataset.localRequest,version:Number(el.dataset.version),state:el.value});el.dataset.version=d.version;el.closest('article').querySelector('[role=status]').textContent='Andamento salvo. Combine a confirmação com o cliente pelo WhatsApp.';}catch(err){el.closest('article').querySelector('[role=status]').textContent=err.message;}finally{el.disabled=false;}});
 document.addEventListener('click',e=>{const btn=e.target.closest('[data-local-invite]');if(!active||!btn)return;const r=rows.find(x=>x.id===btn.dataset.localInvite);if(!r)return;openDialog('Acesso do responsável',`<form id="local-invite" data-id="${esc(r.id)}"><p>Novas empresas devem usar o cadastro público. Para vincular uma empresa antiga sem acesso, gere um link pessoal para o responsável definir sua senha. O acesso permite editar a página e consultar os contatos deste negócio.</p><label class="p-field">E-mail de login<input name="email" type="email" required autocomplete="off" maxlength="254"></label><p>Ao renovar, o convite anterior deixa de funcionar. O link vence em 72 horas.</p><p role="alert"></p><button class="p-button primary">Gerar convite de acesso</button></form>`);});
 document.addEventListener('submit',async e=>{if(e.target.id!=='local-invite'||!active)return;e.preventDefault();const f=e.target,b=f.querySelector('button');b.disabled=true;try{const d=await api('/api/portal/local-admin','POST',{action:'invite',id:f.dataset.id,email:f.elements.email.value});inviteDraft={...d,id:f.dataset.id,requestId:crypto.randomUUID()};const status=await api('/api/portal/local-admin','POST',{action:'invite-status',id:f.dataset.id});inviteDraft.official=status;openDialog('Convite pronto para enviar',`<p><strong>Login:</strong> ${esc(d.email)}</p><p>Convite válido até ${new Date(d.expiresAt).toLocaleString('pt-BR')}. Envie somente ao responsável.</p><label class="p-field">Mensagem de acesso<textarea rows="10" readonly>${esc(d.message)}</textarea></label><p><strong>Remetente oficial:</strong> ${esc(status.phone||'Não configurado')}</p>${!status.insideWindow&&status.template?'<label><input id="local-invite-consent" type="checkbox"> O responsável autorizou o contato pelo WhatsApp.</label><label class="p-field">Onde e quando autorizou<textarea id="local-invite-evidence" maxlength="1000"></textarea></label>':''}<button class="p-button primary" type="button" data-send-local-invite ${!status.configured||(!status.insideWindow&&!status.template)?'disabled':''}>Enviar pelo WhatsApp oficial da Helpu</button><p id="local-invite-result" role="status">${!status.configured?'Ative a caixa de atendimento oficial no administrativo.':!status.insideWindow&&!status.template?'Este contato precisa enviar uma mensagem ao número oficial primeiro. Para iniciar o convite sem uma conversa recente, configure o modelo aprovado helpu_local_acesso.':'O envio será feito pelo número oficial e ficará registrado no atendimento. Ao enviar, você assume a conversa.'}</p>${status.phone?`<p>Link do atendimento oficial para o cliente: <a href="https://wa.me/${encodeURIComponent(status.phone.replace(/\D/g,''))}" target="_blank" rel="noopener">Abrir conversa com a Helpu ↗</a></p>`:''}<a href="/admin.html#/whatsapp">Ir ao atendimento WhatsApp ↗</a>`);}catch(err){f.querySelector('[role=alert]').textContent=err.message;}finally{b.disabled=false;}});
 document.addEventListener('click',async e=>{const b=e.target.closest('[data-send-local-invite]');if(!b||!active||!inviteDraft)return;b.disabled=true;const output=document.querySelector('#local-invite-result');output.textContent='Enviando pelo número oficial…';try{const d=await api('/api/portal/local-admin','POST',{action:'invite-send',id:inviteDraft.id,token:inviteDraft.url.split('ativar=')[1],requestId:inviteDraft.requestId,consent:document.querySelector('#local-invite-consent')?.checked===true,evidence:document.querySelector('#local-invite-evidence')?.value||''});output.textContent=['accepted','sent','delivered','read'].includes(d.state)?'Convite aceito para envio pelo WhatsApp oficial. Acompanhe a entrega em Atendimento WhatsApp.':d.state==='uncertain'?'Envio aguardando confirmação. Confira o atendimento antes de tentar novamente.':'Não foi possível concluir. Confira o status no atendimento WhatsApp.';}catch(err){output.textContent=err.message;b.disabled=false;}});
 document.addEventListener('click',e=>{if(!active)return;if(e.target.closest('[data-add-item]')){const el=document.querySelector('#local-catalog');if(el.children.length>=30){toast('Limite de 30 itens nesta página.',true);return;}el.insertAdjacentHTML('beforeend',itemRow());}if(e.target.closest('[data-remove-item]'))e.target.closest('.local-item').remove();const rm=e.target.closest('[data-remove-photo]'),cover=e.target.closest('[data-cover-photo]');if(rm){editingPhotos=editingPhotos.filter(id=>id!==rm.dataset.removePhoto);drawPhotos();}if(cover){editingPhotos=[cover.dataset.coverPhoto,...editingPhotos.filter(id=>id!==cover.dataset.coverPhoto)];drawPhotos();}});
 document.addEventListener('change',async e=>{if(e.target.id!=='local-photo-input'||!active)return;const f=document.querySelector('#local-editor'),input=e.target,button=f.querySelector('[type=submit]'),status=f.querySelector('#local-upload-status');const files=[...input.files];if(files.length+editingPhotos.length>6){status.textContent='Use até seis fotos por negócio.';input.value='';return;}input.disabled=true;button.disabled=true;try{for(const file of files){if(!['image/png','image/jpeg','image/webp'].includes(file.type))throw Error('Use JPG, PNG ou WebP.');status.textContent='Enviando '+file.name+'…';const asset=await uploadFile('/api/portal/'+encodeURIComponent(getState().company.id)+'/files',file);if(!f.isConnected)return;editingPhotos.push(asset.id);drawPhotos();}status.textContent='Fotos enviadas. Salve o cadastro para aplicar.';}catch(err){status.textContent=err.message;}finally{input.disabled=false;button.disabled=false;input.value='';}});
 document.addEventListener('click',e=>{const b=e.target.closest('[data-local-edit]');if(b&&active){const r=rows.find(r=>r.id===b.dataset.localEdit);if(r)edit(r);}});
 document.addEventListener('input',e=>{if(active&&e.target.id==='local-search')draw();});document.addEventListener('change',e=>{if(active&&e.target.id==='local-filter')draw();});
 document.addEventListener('submit',async e=>{if(e.target.id!=='local-editor'||!active)return;e.preventDefault();const f=e.target,b=f.querySelector('button[type=submit]');b.disabled=true;try{const d=Object.fromEntries(new FormData(f));d.id=f.dataset.id;d.version=Number(f.dataset.version);d.approval=false;d.events=readEvents(f);d.logoId=editingLogo;d.photos=[...editingPhotos];d.catalog=[...f.querySelectorAll('.local-item')].map(el=>({...readItemExtras(el,rows.find(r=>r.id===f.dataset.id)?.catalog?.find(x=>x.id===el.dataset.itemId)||{}),id:el.dataset.itemId,name:el.querySelector('[data-item-name]').value,description:el.querySelector('[data-item-description]').value,priceCents:el.querySelector('[data-item-price]').value===''?null:Math.round(Number(el.querySelector('[data-item-price]').value)*100),available:el.querySelector('[data-item-available]').checked}));await api('/api/portal/local-admin','POST',d);closeDialog();toast('Cadastro salvo.');await load();}catch(err){f.querySelector('#local-edit-error').textContent=err.message;}finally{b.disabled=false;}});
 document.addEventListener('click',e=>{
  const b=e.target.closest('[data-local-delete],[data-local-restore]');if(!active||!b)return;
  const restore=b.hasAttribute('data-local-restore'),r=rows.find(x=>x.id===(restore?b.dataset.localRestore:b.dataset.localDelete));if(!r)return;
  openDialog(restore?'Restaurar empresa':'Excluir empresa do catálogo',`<form id="local-removal" data-id="${esc(r.id)}" data-version="${r.version}" data-action="${restore?'restore':'delete'}"><p><strong>${esc(r.name)}</strong></p><p>${restore?'O cadastro voltará como Inativo. Revise os dados antes de publicar novamente.':'A empresa e seus anúncios de produtos sairão do público. O responsável perderá acesso ao portal enquanto a empresa estiver excluída. Você poderá restaurá-la pelo filtro Excluídas.'}</p><p role="alert"></p><button type="submit" class="p-button primary">${restore?'Restaurar cadastro':'Confirmar exclusão do catálogo'}</button></form>`);
 });
 document.addEventListener('submit',async e=>{
  if(!active||e.target.id!=='local-removal')return;e.preventDefault();const f=e.target,b=f.querySelector('button');b.disabled=true;
  try{await api('/api/portal/local-admin','POST',{action:f.dataset.action,id:f.dataset.id,version:Number(f.dataset.version)});closeDialog();toast(f.dataset.action==='restore'?'Cadastro restaurado como Inativo.':'Empresa excluída do catálogo.');await load();}
  catch(err){f.querySelector('[role=alert]').textContent=err.message;}finally{b.disabled=false;}
 });
 return {page,mount(view){active=view==='local';management.mount(active);if(active)load();else ++seq;}};
}
